/**
 * After-commit effects runtime (generated by Quickback — do not edit).
 *
 * `effects.enqueue(name, fn)` queues a best-effort side effect from inside
 * an action's `execute`; declared `afterCommit` hooks and enqueued effects
 * run after `execute` returns successfully. Failures are logged and never
 * affect the response.
 */
import { redactError } from './errors';

export interface QbEnqueuedEffect {
  name: string;
  fn: (...args: any[]) => any;
  /** Run before the response (a tenant object's queue outbox row), not deferred. */
  sync?: true;
}

export interface QbEffects {
  /**
   * Queue a best-effort side effect to run after the action commits.
   * Same semantics as a non-blocking `afterCommit` hook: scheduled via
   * `executionCtx.waitUntil` when available, failures logged as
   * `[<actionName>] afterCommit:<name> failed`, never affects the response.
   * Effects enqueued by an `execute` that later throws are dropped.
   */
  enqueue(name: string, fn: (...args: any[]) => any): void;
  /**
   * Send `message` to the queue binding `binding` after the action
   * commits (dropped like any effect if `execute` throws or dry-runs). In a
   * tenant object (plan 032) it goes through the outbox instead: written
   * before the response, sent by the edge with tenantId + dedupeKey stamped.
   */
  enqueue(binding: string, message: { type: string; [field: string]: unknown }): void;
  /** @internal Snapshot the queue length (bulk per-record rollback). */
  __mark(): number;
  /** @internal Drop effects enqueued after `mark` (record's execute threw / dry-ran). */
  __rollback(mark: number): void;
  /** @internal Remove and return all queued effects. */
  __drain(): QbEnqueuedEffect[];
}

export function createEffects(env?: any): QbEffects {
  const queue: QbEnqueuedEffect[] = [];
  return {
    enqueue(name: string, fn: any): void {
      if (typeof name !== 'string' || name.length === 0) {
        throw new Error('effects.enqueue: name must be a non-empty string');
      }
      if (fn && typeof fn === 'object' && !Array.isArray(fn)) {
        // Queue form: (binding, message).
        const runtime = env?.__qbTenant?.runtime;
        if (runtime) {
          queue.push({ name: 'enqueue:' + name, fn: () => runtime.enqueue(name, fn), sync: true });
        } else {
          queue.push({ name: 'enqueue:' + name, fn: () => {
            const binding = env?.[name];
            if (!binding || typeof binding.send !== 'function') throw new Error(`effects.enqueue: queue binding "${name}" is not bound`);
            return binding.send(fn);
          } });
        }
        return;
      }
      if (typeof fn !== 'function') {
        throw new Error(`effects.enqueue("${name}"): fn must be a function`);
      }
      queue.push({ name, fn });
    },
    __mark(): number {
      return queue.length;
    },
    __rollback(mark: number): void {
      if (mark >= 0 && mark < queue.length) queue.length = mark;
    },
    __drain(): QbEnqueuedEffect[] {
      return queue.splice(0, queue.length);
    },
  };
}

interface ResolvedHook {
  name: string;
  blocking: boolean;
  run: (actx: any, result: any) => any;
}

/**
 * Normalize a declared `afterCommit` map. Each entry is either a bare
 * function (non-blocking) or `{ blocking?, run }`. Insertion order of the
 * object literal is the declared order.
 */
function resolveHooks(hooks: Record<string, any> | undefined | null): ResolvedHook[] {
  const resolved: ResolvedHook[] = [];
  if (!hooks || typeof hooks !== 'object') return resolved;
  for (const [name, raw] of Object.entries(hooks)) {
    if (typeof raw === 'function') {
      resolved.push({ name, blocking: false, run: raw });
    } else if (raw && typeof raw === 'object' && typeof raw.run === 'function') {
      resolved.push({ name, blocking: raw.blocking === true, run: raw.run });
    }
    // Anything else was rejected at compile time; skip defensively at runtime.
  }
  return resolved;
}

/**
 * Run an action's after-commit phase. Call ONLY after `execute` returned
 * successfully (the route's catch path must not reach this).
 *
 *  1. `result.dryRun === true` → skip everything, drop enqueued effects.
 *  2. Blocking hooks: awaited sequentially in declared order (the response
 *     depends on them), each independently wrapped.
 *  3. Non-blocking hooks (declared order) then enqueued effects (enqueue
 *     order): run sequentially inside ONE deferred task handed to
 *     `waitUntil`; when scheduling is unavailable the task floats
 *     (`void task`) — the fixture-proven Bun/Node fallback.
 */
export async function runAfterCommit(opts: {
  actionName: string;
  hooks: Record<string, any> | undefined | null;
  effects: QbEffects;
  actx: any;
  result: any;
  /** Try to schedule the deferred task; return false to float it instead. */
  waitUntil: (task: Promise<any>) => boolean;
}): Promise<void> {
  const { actionName, hooks, effects, actx, result } = opts;
  // Always drain — a dry run must also DROP effects, not leak them into a
  // later runAfterCommit call on the same request.
  const enqueued = effects.__drain();
  if (result && typeof result === 'object' && (result as any).dryRun === true) return;

  const declared = resolveHooks(hooks);
  const runOne = async (name: string, fn: (a: any, r: any) => any): Promise<void> => {
    try {
      await fn(actx, result);
    } catch (err) {
      console.warn(`[${actionName}] afterCommit:${name} failed`, redactError(err));
    }
  };

  for (const hook of declared) {
    if (hook.blocking) await runOne(hook.name, hook.run);
  }

  // A tenant object's queue sends become outbox rows before the response, so
  // the edge drains them with this request.
  // They throw (TENANT_QUEUE_*): the response reports the failure.
  for (const e of enqueued) {
    if (e.sync) await e.fn(actx, result);
  }

  const deferred: Array<{ name: string; fn: (a: any, r: any) => any }> = [
    ...declared.filter((h) => !h.blocking).map((h) => ({ name: h.name, fn: h.run })),
    ...enqueued.filter((e) => !e.sync).map((e) => ({ name: e.name, fn: e.fn as (a: any, r: any) => any })),
  ];
  if (deferred.length === 0) return;

  const task = (async () => {
    for (const d of deferred) await runOne(d.name, d.fn);
  })();
  let scheduled = false;
  try {
    scheduled = opts.waitUntil(task) === true;
  } catch {
    scheduled = false;
  }
  if (!scheduled) void task;
}

