export interface QbEmitCrudBinding {
  actionName: string;
  /** Frame table key — same string auto-CRUD frames use. */
  table: string;
  realtime: any;
  effects: QbEffects;
  /** true → frames ride the after-commit effects queue. */
  async: boolean;
  allowed: Array<'insert' | 'update' | 'delete'>;
  /** Per-row target resolver; null → emit skipped. */
  target: (row: any) => any;
  /** Trailing options for realtime.insert/update/delete (roles/masking). */
  options?: Record<string, any>;
}

/**
 * Build the pre-bound `emitCrud(row, oldRow?)` injected into actions that
 * declare `emit:` (manual mode). Op inference: (row) → insert,
 * (row, oldRow) → update, (null, oldRow) → delete. Best-effort — failures
 * log as `[<actionName>] afterCommit:emit failed` and never throw.
 */
export function createEmitCrud(binding: QbEmitCrudBinding) {
  const send = async (row: any, oldRow?: any): Promise<void> => {
    try {
      const op = row != null && oldRow != null
        ? 'update'
        : row != null
          ? 'insert'
          : oldRow != null
            ? 'delete'
            : null;
      if (!op) return;
      if (!binding.allowed.includes(op as any)) {
        console.warn(`[${binding.actionName}] afterCommit:emit skipped — op "${op}" not declared in emit.on`);
        return;
      }
      const target = binding.target(row ?? oldRow);
      if (!target) return;
      if (op === 'insert') await binding.realtime.insert(binding.table, row, target, binding.options);
      else if (op === 'update') await binding.realtime.update(binding.table, row, oldRow, target, binding.options);
      else await binding.realtime.delete(binding.table, oldRow, target, binding.options);
    } catch (err) {
      console.warn(`[${binding.actionName}] afterCommit:emit failed`, redactError(err));
    }
  };
  return (row: any, oldRow?: any): Promise<void> | void => {
    if (binding.async) {
      binding.effects.enqueue('emit:' + binding.table, () => send(row, oldRow));
      return;
    }
    return send(row, oldRow);
  };
}

/**
 * Named invalidation binding (Part A). Compiler-baked: wireName/version are
 * literals; `variants` carries each variant's reason + declared payload keys
 * (the projection boundary); `target` is the resolved delivery profile.
 */
export interface QbNamedInvalidationBinding {
  actionName: string;
  binding: string;
  realtime: any;
  effects: QbEffects;
  wireName: string;
  version: number;
  variants: Record<string, { reason: string; keys: string[] }>;
  target: { scopeKeyFrom?: string; organizationId?: string; userIdFrom?: string };
  /**
   * The acting request's identity, threaded only for the account lane so
   * `organizationId: "ctx.activeOrgId"` / `userIdFrom: "ctx.userId"` resolve
   * at runtime instead of landing as literal strings (#625).
   */
  ctx?: { activeOrgId?: string; userId?: string };
  targetRoles: string[];
  /**
   * Scoped (firewalled) db handle, passed to the recipients resolver. Present
   * only when `resolveRecipients` is set — the resolver reads committed state
   * through the SAME firewall the actor sees (privacy: it can't resolve
   * identities the actor couldn't read).
   */
  db?: any;
  /**
   * Recipients resolver (Slice 2): `({ db, input, recipient }) => Identity[]`.
   * When present, the broadcast is NARROWED to `scope ∩ roles ∩ recipient-tags`
   * — the resolver can only narrow, never widen. Fail-closed: a throw or `[]`
   * resolves to nobody (`targetTags: []`).
   */
  resolveRecipients?: (a: { db: any; input: any; recipient: any }) => any;
  /** Declared keys the resolver input is projected to (from `{ ...meta, ...payload }`). */
  recipientsInputKeys?: string[];
  /**
   * Fail-closed marker baked by the compiler whenever this binding targets a
   * recipients-narrowed profile. The runtime gates `targetTags` on THIS flag
   * (not on `resolveRecipients` being present), so a profile declared
   * recipients-narrowed whose `resolveRecipients` is missing/renamed at
   * runtime still narrows to nobody (`targetTags: []`) — it NEVER reverts to
   * role-only fanout, which would WIDEN the audience.
   */
  recipientsNarrowed?: boolean;
}

/**
 * Build the pre-bound `invalidate.<binding>.<variant>(payload, meta?)` handle
 * (Part A). Each call appends ONE best-effort after-commit effect that:
 *  - projects the payload to the variant's DECLARED keys (undeclared fields
 *    never reach the wire),
 *  - resolves the delivery target from the payload/meta (fail-closed: a
 *    missing scope value or userId → nobody),
 *  - sends exactly one `realtime.broadcast(wireName, { version, reason,
 *    ...projected }, target, { targetRoles })` frame — the dotted wireName is
 *    preserved verbatim (NOT routed through the ns-prefixed method).
 * Discarded on execute throw / `dryRun` (rides the effects collector).
 */
export function createNamedInvalidation(
  binding: QbNamedInvalidationBinding,
): Record<string, (payload: any, meta?: any) => void> {
  const handle: Record<string, (payload: any, meta?: any) => void> = {};
  for (const variant of Object.keys(binding.variants)) {
    const spec = binding.variants[variant];
    handle[variant] = (payload: any, meta?: any): void => {
      binding.effects.enqueue('invalidate:' + binding.binding, async () => {
        try {
          const projected: Record<string, unknown> = {};
          for (const k of spec.keys) {
            if (payload != null && Object.prototype.hasOwnProperty.call(payload, k)) projected[k] = payload[k];
          }
          const target = __qbResolveInvalidationTarget(binding.target, payload, meta, binding.ctx);
          if (!target) return; // fail-closed: no resolvable audience → nobody
          // Recipients (Slice 2): resolve identities → tags and NARROW the
          // broadcast. The Broadcaster AND-composes scope ∩ roles ∩ targetTags,
          // so `targetTags: []` selects nobody — a resolver can only narrow,
          // never widen. ALWAYS pass `targetTags` when a resolver exists (even
          // `[]`); OMITTING it reverts to role-only fanout, which WIDENS.
          const options: Record<string, unknown> = { targetRoles: binding.targetRoles };
          // Gate on the baked `recipientsNarrowed` marker, NOT on
          // `resolveRecipients` being a live function. If the compiler declared
          // this binding recipients-narrowed but the resolver evaluates falsy at
          // runtime (missing/renamed), fail CLOSED to `targetTags: []` (nobody)
          // rather than OMITTING targetTags — omission reverts to role-only
          // fanout, which WIDENS. A resolver can only ever narrow.
          if (binding.recipientsNarrowed) {
            options.targetTags = typeof binding.resolveRecipients === 'function'
              ? await __qbResolveRecipientTags(binding, projected, meta)
              : [];
          }
          await binding.realtime.broadcast(
            binding.wireName,
            // Envelope wins: baked `version`/`reason` spread LAST so a declared
            // payload key of the same name can't overwrite the contract fields
            // (belt-and-suspenders — the compiler also rejects reserved keys).
            { ...projected, version: binding.version, reason: spec.reason },
            target,
            options,
          );
        } catch (err) {
          console.warn('[' + binding.actionName + '] afterCommit:invalidate:' + binding.binding + ' failed', redactError(err));
        }
      });
    };
  }
  return handle;
}

/** Resolve a delivery target from payload/meta. Fail-closed → null (nobody). */
function __qbResolveInvalidationTarget(
  t: { scopeKeyFrom?: string; organizationId?: string; userIdFrom?: string },
  payload: any,
  meta?: any,
  ctx?: { activeOrgId?: string; userId?: string },
): any {
  const read = (key: string): unknown => {
    if (payload != null && payload[key] != null) return payload[key];
    if (meta != null && meta[key] != null) return meta[key];
    return null;
  };
  // Account-lane value: `ctx.activeOrgId` / `ctx.userId` from the request,
  // `payload.<key>` / `meta.<key>` from the call, else a literal.
  const ref = (value: string): unknown => {
    if (value === 'ctx.activeOrgId') return ctx?.activeOrgId ?? null;
    if (value === 'ctx.userId') return ctx?.userId ?? null;
    const m = /^(payload|meta)\.([A-Za-z_$][A-Za-z0-9_$]*)$/.exec(value);
    if (m) return read(m[2]);
    return value;
  };
  if (t.scopeKeyFrom) {
    let missing = false;
    const scopeKey = t.scopeKeyFrom.replace(/\{([A-Za-z_$][A-Za-z0-9_$]*)\}/g, (_m: string, col: string) => {
      const v = read(col);
      if (v == null) { missing = true; return ''; }
      return String(v);
    });
    return missing ? null : { scopeKey };
  }
  if (t.organizationId && t.userIdFrom) {
    const organizationId = ref(t.organizationId);
    if (organizationId == null) return null;
    // userIdFrom: a reference (above), else a payload/meta key — a dotted
    // path such as 'recipient.userId' resolves its last segment.
    const userId = t.userIdFrom.startsWith('ctx.') || /^(payload|meta)\./.test(t.userIdFrom)
      ? ref(t.userIdFrom)
      : read(t.userIdFrom.split('.').pop() as string);
    if (userId == null) return null;
    return { organizationId: String(organizationId), userId: String(userId) };
  }
  return null;
}

/**
 * Resolve a recipients profile (Slice 2) to a deduped identity-tag list —
 * ALWAYS fail-closed. The delivery is NARROWED to `scope ∩ roles ∩ these tags`
 * by the Broadcaster, so an empty return selects nobody. Contract:
 *  - input is projected from `{ ...meta, ...payload }` to the DECLARED input
 *    keys only (payload wins on conflict) — undeclared fields never reach the
 *    resolver.
 *  - the resolver mints identities via `recipient.user` / `recipient.scope`;
 *    a throw resolves to `[]` (nobody), never a wider audience.
 *  - only well-formed Identity objects convert to tags; raw strings or
 *    `targetTags`-shaped returns are rejected (a resolver must NOT hand back
 *    raw tags).
 *  - capped at 500 tags (best-effort signal): over-cap truncates + warns
 *    rather than failing to nobody.
 */
async function __qbResolveRecipientTags(
  binding: QbNamedInvalidationBinding,
  payload: any,
  meta: any,
): Promise<string[]> {
  // `payload` here is already projected to the variant's declared keys. With
  // declared input keys, narrow further; for the reference form (keys unknown
  // at compile time) the declared payload + meta IS the input — projecting to
  // [] handed the resolver nothing and delivered to nobody (#625).
  const merged: Record<string, unknown> = { ...(meta ?? {}), ...(payload ?? {}) };
  let input: Record<string, unknown> = merged;
  if (binding.recipientsInputKeys) {
    input = {};
    for (const k of binding.recipientsInputKeys) {
      if (Object.prototype.hasOwnProperty.call(merged, k)) input[k] = merged[k];
    }
  }
  const recipient = {
    user: (id: string) => ({ t: 'user', id: String(id) }),
    scope: (a: { kind: string; subjectId: string }) => ({
      t: 'scope',
      kind: String(a?.kind),
      subjectId: String(a?.subjectId),
    }),
  };
  let ids: any[] = [];
  try {
    const r = await binding.resolveRecipients!({ db: binding.db, input, recipient });
    ids = Array.isArray(r) ? r : [];
  } catch (e) {
    console.warn(
      '[' + binding.actionName + '] afterCommit:invalidate:' + binding.binding +
        ' recipients resolver threw — narrowing to nobody',
      e,
    );
    return []; // fail-closed
  }
  const tags = new Set<string>();
  for (const it of ids) {
    // Reject raw strings / `targetTags`-shaped returns — identities only.
    if (!it || typeof it !== 'object') continue;
    if (it.t === 'user' && it.id != null) tags.add('user:' + String(it.id));
    else if (it.t === 'scope' && it.kind != null && it.subjectId != null) {
      tags.add('scope:' + String(it.kind) + ':' + String(it.subjectId));
    }
  }
  let out = Array.from(tags);
  if (out.length > 500) {
    console.warn(
      '[' + binding.actionName + '] afterCommit:invalidate:' + binding.binding +
        ' resolved ' + out.length + ' recipients — capping at 500',
    );
    out = out.slice(0, 500);
  }
  return out;
}

/**
 * Enqueue after-commit frames for writes captured by the scoped db
 * (`realtime.emitFromActions` — auto mode). One effect per captured row;
 * failures are isolated per-frame by the runAfterCommit wrapper. Entries
 * are cleared so a later call can't double-emit.
 */
/**
 * Send `messages` to a Cloudflare Queue in chunks of `batchSize`
 * (Queues cap sendBatch at 100 messages). Falls back to per-message
 * `send` when the binding has no `sendBatch`. Sequential per chunk so
 * partial failure has a clean prefix.
 */
export async function sendQueueBatched(
  queue: { send: (msg: any) => Promise<any>; sendBatch?: (msgs: Array<{ body: any }>) => Promise<any> },
  messages: any[],
  batchSize: number = 100,
): Promise<void> {
  const size = Math.max(1, Math.min(100, batchSize));
  for (let i = 0; i < messages.length; i += size) {
    const chunk = messages.slice(i, i + size);
    if (typeof queue.sendBatch === 'function') {
      await queue.sendBatch(chunk.map((body) => ({ body })));
    } else {
      for (const body of chunk) await queue.send(body);
    }
  }
}

export function enqueueCapturedEmits(opts: {
  actionName: string;
  table: string;
  realtime: any;
  effects: QbEffects;
  entries: Array<{ op: 'insert' | 'update' | 'delete'; new?: any; old?: any }>;
  ops: { insert: boolean; update: boolean; delete: boolean };
  target: (row: any) => any;
  options?: Record<string, any>;
}): void {
  for (const e of opts.entries) {
    if (!opts.ops[e.op]) continue;
    const entry = e;
    opts.effects.enqueue('emit:' + opts.table, async () => {
      const target = opts.target(entry.new ?? entry.old);
      if (!target) return;
      if (entry.op === 'insert') await opts.realtime.insert(opts.table, entry.new, target, opts.options);
      else if (entry.op === 'update') await opts.realtime.update(opts.table, entry.new, entry.old, target, opts.options);
      else await opts.realtime.delete(opts.table, entry.old, target, opts.options);
    });
  }
  opts.entries.length = 0;
}

